import sqlite3,json,collections,sys,datetime as dt
sys.path.insert(0,'.')
from mlops import scoring, metrics
from sklearn.metrics import roc_auc_score as AUC
c=sqlite3.connect('data/appointments.sqlite'); c.row_factory=sqlite3.Row
coef=json.loads(c.execute("select coefficients_json from model_registry where model_version='noshow-v3.1'").fetchone()[0])
ev=collections.defaultdict(list)
for p,d,t in c.execute("select patient_id,event_on,event_type from attendance_events where event_type='DID_NOT_ATTEND'"): ev[p].append(d)
rows=c.execute("""select a.*, f.prior_no_shows_12m sp, s.score s31, v.score s4, cl.size_band, cl.ramp_group, r.outcome call
 from appointments a join feature_snapshots f using(appt_id) join clinics cl using(clinic_id)
 join model_scores s on s.appt_id=a.appt_id and s.model_version='noshow-v3.1'
 join model_scores v on v.appt_id=a.appt_id and v.model_version='noshow-v4.0'
 left join reminder_calls r on r.appt_id=a.appt_id""").fetchall()
EXC={'CL-001','CL-005','CL-012','CL-028','CL-038'}
def c365(r):
    lo=(dt.date.fromisoformat(r['booked_on'])-dt.timedelta(days=365)).isoformat()
    return sum(1 for d in ev[r['patient_id']] if lo<=d<r['booked_on'])
D=[]
for r in rows:
    d=dict(r); d['rec']=scoring.score(coef,c365(r),r['lead_time_days'],r['deprivation_decile'],r['distance_km'],r['age_band'],r['appointment_type'])
    d['cur']=scoring.score(coef,r['prior_no_show_count'],r['lead_time_days'],r['deprivation_decile'],r['distance_km'],r['age_band'],r['appointment_type'])
    D.append(d)
import pickle; pickle.dump(D,open('/tmp/D.pkl','wb'))
def rep(name,sub):
    y=[d['no_show'] for d in sub]
    print(name,len(sub),round(100*sum(y)/len(y),2),*[round(AUC(y,[d[k] for d in sub]),4) for k in ('s31','rec','cur','s4')])
for wl,wh in [(1,26),(27,40),(41,52),(33,52)]:
    for pn,f in [('all',lambda d:True),('prog',lambda d:d['clinic_id'] not in EXC),('excl',lambda d:d['clinic_id'] in EXC)]:
        rep(f"w{wl}-{wh} {pn}",[d for d in D if wl<=d['week']<=wh and f(d)])
EOF
