for per,(lo,hi) in [('pre',(1,26)),('win',(41,52))]:
  for sb in ('SMALL','MEDIUM','LARGE'):
    for band in (True,False):
      g=lambda e:[d for d in D if lo<=d['week']<=hi and d['size_band']==sb and (d['s31']>=t)==band and (d['clinic_id'] in EXC)==e]
      print(per,sb,'band' if band else 'below',rate(g(False)),rate(g(True)))
for per,(lo,hi) in [('pre',(1,26)),('win',(41,52))]:
  for e in (False,True):
    s=[d for d in D if lo<=d['week']<=hi and (d['clinic_id'] in EXC)==e]
    print(per,e,rate(s),'partner%',round(100*sum(d['referral_source']!='GP' for d in s)/len(s),1), rate([d for d in s if d['referral_source']!='GP']), rate([d for d in s if d['referral_source']=='GP']))
# reached vs not
s=[d for d in D if 41<=d['week']<=52 and d['call']]
for o in ('REACHED','NO_ANSWER','VOICEMAIL'): print(o,rate([d for d in s if d['call']==o]))
EOF
